    declaredFields.filter { it.isPublicAnd(static = true) }.map { it.name }.sorted()

fun main() {
    val payment: Class<*> = Payment::class.java
    val companion: Class<*> = Payment.Companion::class.java
    val file: Class<*> = Class.forName("MainKt")

    println("1 프로퍼티 getter   = " + payment.publicMethods(static = false))
    println("2 Payment static    = " + payment.publicMethods(static = true))
    println("3 static 필드       = " + payment.publicStaticFields())
    println("4 Companion 메서드  = " + companion.publicMethods(static = false))
    println("5 describe 오버로드 = " + file.declaredMethods.count { it.name == "describe" })
    println("6 파일 클래스 메서드 = " + file.publicMethods(static = true))
}

exercise.solution:
class Payment(
    val id: Long,
    val paid: Boolean,       // Java 에서는 getPaid(). is 로 시작할 때만 이름이 그대로 간다
    val isRefunded: Boolean, // → isRefunded()
) {
    companion object {
        const val TYPE = "PAYMENT"       // 컴파일 타임 상수 → public static final

        @JvmField
        val CURRENCY = "KRW"             // 런타임 static 필드

        val REGION = "KR"                // 대조군: private 필드 + Companion.getREGION()

        @JvmStatic
        fun of(id: Long): Payment = Payment(id, false, false)  // Companion 의 of 는 그대로 남는다
    }
}

@JvmOverloads  // 기본값 2개 → 오버로드 3개를 실제로 생성
fun describe(id: Long, prefix: String = "P", suffix: String = ""): String = "$prefix$id$suffix"

@JvmName("totalOf")
fun total(a: Int, b: Int): Int = a + b

@JvmSynthetic  // ACC_SYNTHETIC — Java 컴파일러에게 안 보인다
fun kotlinOnly(): Int = 42

// 학습 서버는 import 를 못 쓰므로 java.* 는 정규화된 이름으로 부른다
private fun java.lang.reflect.Member.isPublicAnd(static: Boolean): Boolean =
    java.lang.reflect.Modifier.isPublic(modifiers) &&
        java.lang.reflect.Modifier.isStatic(modifiers) == static

private fun Class<*>.publicMethods(static: Boolean): List<String> =
    declaredMethods.filter { !it.isSynthetic && it.isPublicAnd(static) }.map { it.name }.sorted()

private fun Class<*>.publicStaticFields(): List<String> =
    declaredFields.filter { it.isPublicAnd(static = true) }.map { it.name }.sorted()

fun main() {
    val payment: Class<*> = Payment::class.java
    val companion: Class<*> = Payment.Companion::class.java
    val file: Class<*> = Class.forName("MainKt")

    println("1 프로퍼티 getter   = " + payment.publicMethods(static = false))
    println("2 Payment static    = " + payment.publicMethods(static = true))
    println("3 static 필드       = " + payment.publicStaticFields())
    println("4 Companion 메서드  = " + companion.publicMethods(static = false))
    println("5 describe 오버로드 = " + file.declaredMethods.count { it.name == "describe" })
    println("6 파일 클래스 메서드 = " + file.publicMethods(static = true))
}
